:root {
  /* Primary - Genie Purple */
  --color-primary-50:  #F2EEFF;
  --color-primary-100: #DDD2FF;
  --color-primary-200: #B6A1FF;
  --color-primary-300: #8E70FF;
  --color-primary-400: #6E47F2;
  --color-primary-500: #3617CE;
  --color-primary-600: #2A11A8;
  --color-primary-700: #1F0C7F;
  --color-primary-800: #150857;
  --color-primary-900: #0A042E;

  /* Secondary */
  --color-secondary-500: #7C3AED;
  --color-secondary-300: #A78BFA;

  /* Neutral (Dark-first) */
  --color-neutral-0:    #050410;
  --color-neutral-50:   #0B0815;
  --color-neutral-100:  #151125;
  --color-neutral-200:  #2B2440;
  --color-neutral-300:  #403653;
  --color-neutral-500:  #686078;
  --color-neutral-700:  #A39AB5;
  --color-neutral-800:  #C8C1D8;
  --color-neutral-900:  #F7F4FF;
  --color-neutral-1000: #FFFFFF;

  /* Semantic */
  --color-success-bg: #102D1D;
  --color-success-fg: #4ADE80;
  --color-warning-bg: #2A1F00;
  --color-warning-fg: #F6B94B;
  --color-error-bg: #2A0F1A;
  --color-error-fg: #FB7185;
  --color-info-bg: #1A1740;
  --color-info-fg: #B69CFF;

  /* Surface */
  --bg-base: #0B0815;
  --bg-subtle: #151125;
  --bg-elevated: #1C1730;
  --bg-overlay: rgba(5,4,16,0.82);

  /* Text */
  --text-primary: #F7F4FF;
  --text-secondary: #C8C1D8;
  --text-tertiary: #A39AB5;
  --text-on-primary: #FFFFFF;
  --text-disabled: #686078;

  /* Border */
  --border-default: #2B2440;
  --border-subtle: #211B34;
  --border-strong: #403653;
  --border-focus: #A78BFA;
}

[data-theme="light"] {
  --color-success-bg: #EAF8EF;
  --color-success-fg: #138A48;
  --color-warning-bg: #FFF5DC;
  --color-warning-fg: #A96600;
  --color-error-bg: #FDECF1;
  --color-error-fg: #C52F57;
  --color-info-bg: #F0ECFF;
  --color-info-fg: #5B32E6;
  --bg-base: #F8F7FC;
  --bg-subtle: #F1EFF8;
  --bg-elevated: #FFFFFF;
  --bg-overlay: rgba(13,11,18,0.56);
  --text-primary: #1B1823;
  --text-secondary: #5B5568;
  --text-tertiary: #8B8498;
  --text-on-primary: #FFFFFF;
  --text-disabled: #B8B1C4;
  --border-default: #E8E3F1;
  --border-subtle: #F1EFF8;
  --border-strong: #D3CCDF;
  --border-focus: #5B32E6;
}

:root {
  --space-xs:  4px;
  --space-sm:  8px;
  --space-md: 12px;
  --space-lg: 16px;
  --space-xl: 24px;
  --space-2xl: 40px;
  --space-3xl: 64px;
}

:root {
  --radius-none: 0;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-full: 9999px;
}

:root {
  --shadow-none: none;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.30);
  --shadow-md: 0 10px 28px rgba(0,0,0,0.38);
  --shadow-lg: 0 20px 52px rgba(0,0,0,0.52);
  --shadow-glow: 0 14px 38px rgba(124,58,237,0.32);
}

[data-theme="light"] {
  --shadow-sm: 0 1px 3px rgba(29,20,54,0.08);
  --shadow-md: 0 8px 24px rgba(54,23,206,0.12);
  --shadow-lg: 0 18px 48px rgba(29,20,54,0.18);
  --shadow-glow: 0 14px 36px rgba(91,50,230,0.24);
}

.btn {
  min-height: 42px; padding: 0 16px; border: 1px solid transparent;
  border-radius: var(--radius-full); font: 750 13px/1 Pretendard, sans-serif;
  letter-spacing: -0.01em; display: inline-flex; align-items: center;
  justify-content: center; gap: 7px; cursor: pointer;
  transition: transform var(--duration-fast) var(--ease-out),
              background var(--duration-base) var(--ease-out),
              box-shadow var(--duration-base) var(--ease-out);
}
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(0) scale(.98); }
.btn:disabled { opacity: .42; cursor: not-allowed; transform: none; }
.btn.is-loading { color: transparent; position: relative; pointer-events: none; }
.btn.is-loading::after {
  content: ""; position: absolute; width: 14px; height: 14px;
  border: 2px solid rgba(255,255,255,.42); border-top-color: #fff;
  border-radius: 50%;
}
.btn-primary {
  background: linear-gradient(135deg, var(--color-secondary-500), var(--color-primary-500));
  color: var(--text-on-primary); box-shadow: var(--shadow-glow);
}
.btn-primary:hover { box-shadow: 0 12px 30px rgba(91,50,230,.30); }
.btn-secondary {
  background: var(--bg-elevated); color: var(--text-primary);
  border-color: var(--border-default); box-shadow: var(--shadow-sm);
}
.btn-ghost { background: transparent; color: var(--color-primary-300); }
.btn-danger { background: var(--color-error-fg); color: #FFFFFF; }
.btn-play {
  width: 44px; min-height: 44px; padding: 0; border-radius: var(--radius-full);
  background: var(--color-primary-300); color: #0B0815;
}
.search-input {
  width: 100%; background: var(--bg-elevated); border: 1px solid var(--border-default);
  color: var(--text-primary); border-radius: var(--radius-full);
  padding: 11px 16px; font: 500 14px/1.4 inherit;
  transition: border-color var(--duration-fast), box-shadow var(--duration-fast);
}
.search-input::placeholder { color: var(--text-tertiary); }
.search-input:focus {
  outline: 0; border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(167,139,250,0.18);
}
.search-input.is-error { border-color: var(--color-error-fg); }
.search-input:disabled { background: var(--bg-subtle); color: var(--text-disabled); }
.content-card {
  background: var(--bg-elevated); border: 1px solid var(--border-default);
  border-radius: var(--radius-lg); padding: var(--space-lg);
  box-shadow: var(--shadow-sm);
}
.content-card:hover { border-color: var(--border-strong); box-shadow: var(--shadow-md); }
.content-card.is-featured { border-color: rgba(167,139,250,.38); }
.content-card.is-outlined { background: transparent; box-shadow: none; }
.track-card {
  background: var(--bg-elevated); border: 1px solid var(--border-default);
  border-radius: var(--radius-md); padding: 10px; display: grid;
  grid-template-columns: 44px 1fr auto; gap: 10px; align-items: center;
}
.hero-card {
  background: linear-gradient(135deg, #25104E 0%, var(--color-primary-500) 58%, #8C61FF 100%);
  border-radius: var(--radius-xl); padding: var(--space-xl); color: #FFFFFF;
  position: relative; overflow: hidden; box-shadow: var(--shadow-glow);
}
.tag {
  padding: 6px 11px; border-radius: var(--radius-full);
  font: 700 11px/1 inherit; display: inline-flex; align-items: center;
}
.tag-solid { background: var(--color-primary-300); color: #0B0815; }
.tag-subtle { background: rgba(167,139,250,.14); color: var(--color-primary-200); }
.tag-outline { background: var(--bg-elevated); color: var(--text-secondary); border: 1px solid var(--border-default); }
.tabbar {
  background: var(--bg-elevated); border-top: 1px solid var(--border-default);
  display: grid; grid-template-columns: repeat(5, 1fr); padding: 6px 0;
}
.tabbar .item {
  padding: 6px; text-align: center; font: 650 11px/1.3 inherit;
  color: var(--text-tertiary);
}
.tabbar .item.active { color: var(--color-primary-300); font-weight: 800; }

:root {
  --duration-fast: 120ms;
  --duration-base: 240ms;
  --duration-slow: 400ms;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-purple-fade: cubic-bezier(0.4, 0, 0.2, 1);
}
